text:
fields.map((field, i) => {
                const fieldFilled = formProgress > i;
                const fieldOpacity = interpolate(
                  frame,
                  [60 + i * 20, 80 + i * 20],
                  [0, 1],
                  { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                );
                const textProgress = interpolate(
                  frame,
                  [70 + i * 20, 90 + i * 20],
                  [0, field.value.length],
                  { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                );

                return (
                  <div key={i} style={{ opacity: fieldOpacity }}>
                    <div
                      style={{
                        fontSize: 14,
                        color: COLORS.textMuted,
                        marginBottom: 6,
                        fontFamily: "Inter, sans-serif",
                      }}
                    >
                      {field.label}
                    </div>
                    <div
                      style={{
                        padding: 12,
                        backgroundColor: COLORS.background,
                        borderRadius: 8,
                        border: `2px solid ${fieldFilled ? COLORS.primary : "transparent"}`,
                        fontSize: 14,
                        color: COLORS.text,
                        fontFamily: "Inter, sans-serif",
                      }}
                    >
                      {field.value.slice(0, Math.floor(textProgress))}
                      {!fieldFilled && (
                        <span
                          style={{
                            display: "inline-block",
                            width: 2,
                            height: 16,
                            backgroundColor: COLORS.primary,
                            marginLeft: 2,
                          }}
                        />
                      )}
                    </div>
                  </div>
                );
              })

