useEffect(() => {
    let alive = true;

    const start = async () => {
      try {
        const scanner = new Html5Qrcode(targetIdRef.current, {
          formatsToSupport: [
            Html5QrcodeSupportedFormats.QR_CODE,
            Html5QrcodeSupportedFormats.CODE_128,
            Html5QrcodeSupportedFormats.CODE_39,
            Html5QrcodeSupportedFormats.EAN_13,
            Html5QrcodeSupportedFormats.EAN_8,
            Html5QrcodeSupportedFormats.UPC_A,
            Html5QrcodeSupportedFormats.UPC_E,
          ],
          verbose: false,
        });

        scannerRef.current = scanner;

        await scanner.start(
          { facingMode: "environment" },
          {
            fps: 10,
            qrbox: { width: 250, height: 250 },
            aspectRatio: 1,
          },
          (decodedText) => {
            if (!alive) return;
            globalThis.setTimeout(() => {
              onScanRef.current(decodedText);
            }, 1000);
          },
          () => {},
        );

        if (alive) {
          setIsScanning(true);
          onStartedRef.current?.();
        }
      } catch (error) {
        console.error("Scanner error:", error);
        if (alive) onErrorRef.current("Camera access denied or unavailable");
      }
    };

    const t = window.setTimeout(() => {
      start();
    }, 0);

    return () => {
      alive = false;
      window.clearTimeout(t);

      const scanner = scannerRef.current;
      scannerRef.current = null;
      setIsScanning(false);

      if (!scanner) return;

      void (async () => {
        try {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const anyScanner = scanner as any;
          if (anyScanner?.isScanning) {
            await scanner.stop();
          }
        } catch {
          // ignore
        }

        try {
          scanner.clear();
        } catch {
          // ignore
        }
      })();
    };
    // Stable effect — callbacks accessed via refs so scanner is not torn down on re-renders
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

