markdownLinkCheck(content, { ...options, baseFilePath: filePath }, (err, results) => {
        if (err) {
          reject(err);
          return;
        }

        for (const result of results) {
          if (result.status === "dead") {
            failures.push({
              filePath,
              link: result.link,
              statusCode: result.statusCode,
            });
          }
        }
        resolve();
      })

