    if (value?.startDate) years.push(parseISO(value.startDate).getFullYear());
    if (value?.endDate) years.push(parseISO(value.endDate).getFullYear());
    return years.length ? Math.min(...years) : new Date().getFullYear() - 5;
  }, [bounds, value])

