text:
roles.map((role, i) => {
            const cardOpacity = interpolate(
              frame,
              [30 + i * 15, 60 + i * 15],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );
            const cardScale = spring({
              frame: frame - (30 + i * 15),
              fps: FPS,
              config: { damping: 12, stiffness: 100 },
            });

            return (
              <div
                key={i}
                style={{
                  flex: 1,
                  backgroundColor: COLORS.card,
                  borderRadius: 16,
                  padding: 24,
                  borderTop: `4px solid ${role.color}`,
                  opacity: cardOpacity,
                  transform: `scale(${cardScale})`,
                  display: "flex",
                  flexDirection: "column",
                }}
              >
                <div style={{ fontSize: 48, marginBottom: 16, textAlign: "center" }}>
                  {role.icon}
                </div>
                <div
                  style={{
                    fontSize: 18,
                    fontWeight: "bold",
                    color: COLORS.text,
                    textAlign: "center",
                    fontFamily: "Inter, sans-serif",
                    marginBottom: 4,
                  }}
                >
                  {role.name}
                </div>
                <div
                  style={{
                    fontSize: 14,
                    color: role.color,
                    textAlign: "center",
                    fontFamily: "Inter, sans-serif",
                    marginBottom: 20,
                  }}
                >
                  {role.desc}
                </div>

                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    gap: 8,
                    flex: 1,
                  }}
                >
                  {role.permissions.map((perm, j) => (
                    <div
                      key={j}
                      style={{
                        padding: "8px 12px",
                        backgroundColor: COLORS.background,
                        borderRadius: 6,
                        fontSize: 13,
                        color: COLORS.text,
                        fontFamily: "Inter, sans-serif",
                      }}
                    >
                      ✓ {perm}
                    </div>
                  ))}
                </div>
              </div>
            );
          })

