text:
[
                { email: "sarah@example.com", role: "Admin", time: "2 hours ago" },
                { email: "mike@example.com", role: "User", time: "1 day ago" },
                { email: "john@example.com", role: "User", time: "Just now", isNew: true },
              ].map((invitation, i) => {
                const itemOpacity = invitation.isNew
                  ? inviteSent
                  : interpolate(frame, [200 + i * 20, 230 + i * 20], [0, 1]);

                return (
                  <div
                    key={i}
                    style={{
                      padding: 16,
                      backgroundColor: invitation.isNew
                        ? `${COLORS.success}20`
                        : COLORS.background,
                      borderRadius: 10,
                      border: invitation.isNew
                        ? `1px solid ${COLORS.success}`
                        : "none",
                      opacity: itemOpacity,
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        marginBottom: 4,
                      }}
                    >
                      <span
                        style={{
                          fontSize: 14,
                          fontWeight: "bold",
                          color: COLORS.text,
                          fontFamily: "Inter, sans-serif",
                        }}
                      >
                        {invitation.email}
                      </span>
                      <span
                        style={{
                          padding: "4px 10px",
                          backgroundColor: COLORS.primary,
                          borderRadius: 4,
                          fontSize: 12,
                          color: COLORS.text,
                          fontFamily: "Inter, sans-serif",
                        }}
                      >
                        {invitation.role}
                      </span>
                    </div>
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                      }}
                    >
                      <span
                        style={{
                          fontSize: 12,
                          color: COLORS.textMuted,
                          fontFamily: "Inter, sans-serif",
                        }}
                      >
                        {invitation.isNew ? "Invitation sent ✓" : invitation.time}
                      </span>
                      <span
                        style={{
                          fontSize: 12,
                          color: COLORS.textMuted,
                          cursor: "pointer",
                        }}
                      >
                        Resend
                      </span>
                    </div>
                  </div>
                );
              })

