useEffect(() => {
    let cancelled = false;

    const verifyInvitation = async () => {
      try {
        const token = searchParams.get("token");

        // Handle Supabase auth callback hash (from email link)
        const hashParams = new URLSearchParams(
          window.location.hash.substring(1),
        );
        const accessToken = hashParams.get("access_token");
        const refreshToken = hashParams.get("refresh_token");

        if (accessToken && refreshToken) {
          const { error } = await supabase.auth.setSession({
            access_token: accessToken,
            refresh_token: refreshToken,
          });
          if (error) {
            console.warn("Failed to set session from hash tokens:", error);
          }
          // Clean the hash from URL
          window.history.replaceState(
            null,
            "",
            window.location.pathname + window.location.search,
          );
        }

        // Get current session
        const {
          data: { session },
        } = await supabase.auth.getSession();

        if (!session?.user) {
          setStatus("error");
          setErrorMessage(
            "Session not found. Please click the link in your invitation email.",
          );
          return;
        }

        if (cancelled) return;

        // Load invitation preview from edge function
        const preview = await callAcceptInvitation({
          ...(token ? { token } : {}),
          preview: true,
        });

        if (cancelled) return;

        if (preview.invitation) {
          setInvitationData(preview.invitation);
        }

        // If already accepted, redirect straight to dashboard
        if (preview.invitation?.status === "accepted") {
          try {
            await refreshProfile();
          } catch {
            // ignore
          }
          setStatus("success");
          redirectTimerRef.current = window.setTimeout(
            () => navigate("/", { replace: true }),
            150,
          );
          return;
        }

        setStatus("form");
      } catch (error) {
        console.error("Error verifying invitation:", error);
        if (!cancelled) {
          setStatus("error");
          setErrorMessage(
            (error as Error).message ||
            "Failed to verify invitation. Please try again.",
          );
        }
      }
    };

    verifyInvitation();
    return () => {
      cancelled = true;
    };
  }, [searchParams, callAcceptInvitation, refreshProfile, navigate])

