text:
useMutation({
    mutationFn: async (item: Omit<Item, "created_at" | "updated_at">) => {
      const { vendors: _vendors, ...itemPayload } = item;
      // Trim text fields
      const trimmedItem = {
        ...itemPayload,
        item_code: itemPayload.item_code.trim(),
        vendor_code: itemPayload.vendor_code?.trim() || null,
        vendor_id: itemPayload.vendor_id ?? null,
        description: itemPayload.description.trim(),
        // Set amount = initial_quantity for new items
        amount: itemPayload.initial_quantity,
      };

      const { data, error } = await supabase.from("items").insert(trimmedItem).select().single();
      if (error) throw error;

      // Log the initial stock entry with the current user's id
      const { data: { user } } = await supabase.auth.getUser();
      await supabase.from("transaction_logs").insert({
        user_id: user?.id ?? null,
        project_id: null,
        item_code: trimmedItem.item_code,
        quantity: trimmedItem.initial_quantity,
        transaction_type: "restock",
        entry_type: "added_item",
      });

      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["items"] });
      queryClient.invalidateQueries({ queryKey: ["transaction_logs"] });
      toast.success("Item created successfully");
    },
    onError: (error) => {
      const msg = error.message || "";
      if (msg.toLowerCase().includes("plan item limit reached")) {
        toast.error("Plan item limit reached. Upgrade your plan to add more items.");
        return;
      }
      toast.error(`Failed to create item: ${msg}`);
    },
  })

