useMutation({
    mutationFn: async ({
      item_code,
      quantity,
    }: {
      item_code: string;
      quantity: number;
    }) => {
      // First get current item
      const { data: item, error: itemError } = await supabase
        .from("items")
        .select("amount, restock_level")
        .eq("item_code", item_code)
        .single();

      if (itemError) throw itemError;

      // Update stock: increment both amount AND restock_level
      const newAmount = item.amount + quantity;
      const newRestockLevel = (item.restock_level || 0) + quantity;

      const { error: updateError } = await supabase
        .from("items")
        .update({
          amount: newAmount,
          restock_level: newRestockLevel,
        })
        .eq("item_code", item_code);

      if (updateError) throw updateError;

      // Log the restock with the current user's id
      const { data: { user } } = await supabase.auth.getUser();
      const { error: logError } = await supabase
        .from("transaction_logs")
        .insert({
          user_id: user?.id ?? null,
          project_id: null,
          item_code,
          quantity,
          transaction_type: "restock",
          entry_type: "restock",
        });
      if (logError) throw logError;

      return { newAmount, newRestockLevel };
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["items"] });
      queryClient.invalidateQueries({ queryKey: ["transaction_logs"] });
      toast.success(`Stock updated to ${data.newAmount} units`);
    },
    onError: (error) => toast.error(`Restock failed: ${error.message}`),
  })

