    mutationFn: async (project: Omit<Project, "project_id" | "created_at" | "updated_at">) => {
      const payload = {
        project_name: project.project_name.trim(),
        is_active: project.is_active ?? true,
      };
      const { data, error } = await supabase.from("projects").insert(payload).select().single();
      if (!error) return data;

      // Backward-compatible fallback for databases where is_active migration is not applied yet.
      if (isMissingIsActiveColumnError(error)) {
        const fallback = await supabase
          .from("projects")
          .insert({ project_name: payload.project_name })
          .select()
          .single();
        if (fallback.error) throw fallback.error;
