useMutation({
    mutationFn: async ({
      project_id,
      item_code,
      quantity = 1,
    }: {
      project_id: string;
      item_code: string;
      quantity?: number;
    }) => {
      // Single atomic RPC: locks the stock row (SELECT FOR UPDATE), validates stock,
      // decrements, and writes the transaction_log — all in one Postgres transaction.
      // auth.uid() is captured server-side for user_id.
      const { data, error } = await supabase.rpc("checkout_item", {
        p_item_code: item_code,
        p_quantity: quantity,
        p_project_id: project_id,
      });

      if (error) throw new Error(error.message);
      return data as { success: boolean; new_amount: number; log_id: string };
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["items"] });
      queryClient.invalidateQueries({ queryKey: ["transaction_logs"] });
    },
    onError: (error) => toast.error(`Checkout failed: ${error.message}`),
  })

