useQuery({
    queryKey: ["item_return_allocations", itemCode],
    enabled: Boolean(itemCode),
    queryFn: async () => {
      if (!itemCode) return [];

      const { data, error } = await supabase
        .from("transaction_logs")
        .select(`
          project_id,
          quantity,
          entry_type,
          transaction_type,
          projects!transaction_logs_project_id_fkey(project_id, project_name, is_active)
        `)
        .eq("item_code", itemCode)
        .not("project_id", "is", null);

      if (error) throw error;

      const allocationMap = new Map<string, ItemProjectAllocation>();

      (data || []).forEach((row) => {
        const project = Array.isArray(row.projects) ? row.projects[0] : row.projects;
        if (!project || !row.project_id) return;

        const existing = allocationMap.get(row.project_id) || {
          project_id: row.project_id,
          project_name: project.project_name,
          is_active: project.is_active !== false,
          allocated_quantity: 0,
        };

        if (row.entry_type === "checkout" || (!row.entry_type && row.transaction_type === "checkout")) {
          existing.allocated_quantity += row.quantity;
        } else if (row.entry_type === "return") {
          existing.allocated_quantity -= row.quantity;
        }

        allocationMap.set(row.project_id, existing);
      });

      return Array.from(allocationMap.values())
        .filter((entry) => entry.allocated_quantity > 0)
        .sort((a, b) => a.project_name.localeCompare(b.project_name));
    },
  })

