useQuery({
    queryKey: ["settings", "abc_thresholds"],
    queryFn: async () => {
      const organizationId = await getCurrentOrganizationId();
      const { data, error } = await supabase
        .from("settings")
        .select("value")
        .eq("key", "abc_thresholds")
        .eq("organization_id", organizationId)
        .order("updated_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (error) throw error;

      // If no data exists, return default thresholds
      if (!data || !data.value) {
        // Try to insert default values
        try {
          await supabase.from("settings").insert({
            key: "abc_thresholds",
            value: { A: 30, B: 20, C: 10 },
            organization_id: organizationId,
          });
        } catch (e) {
          // Ignore insert error (might already exist)
        }
        return { A: 30, B: 20, C: 10 };
      }

      return data.value as unknown as ABCThresholds;
    },
  })

