    mutationFn: async (thresholds: ABCThresholds) => {
      const organizationId = await getCurrentOrganizationId();
      const { error, count } = await supabase
        .from("settings")
        .update(
          { value: { A: thresholds.A, B: thresholds.B, C: thresholds.C } },
          { count: "exact" }
        )
        .eq("key", "abc_thresholds")
        .eq("organization_id", organizationId);
      if (error) throw error;

      if (!count) {
        const { error: insertError } = await supabase.from("settings").insert({
          key: "abc_thresholds",
          value: { A: thresholds.A, B: thresholds.B, C: thresholds.C },
          organization_id: organizationId,
        });
        if (insertError) throw insertError;
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["settings"] });
      toast.success("ABC thresholds updated successfully");
    },
    onError: (error) => toast.error(`Failed to update thresholds: ${error.message}`),
  })

