      const fallbackUser = userFromSession ?? (await supabase.auth.getUser()).data.user;
      if (!fallbackUser) {
        return false;
      }

      const metadata = (fallbackUser.user_metadata ?? {}) as Record<string, unknown>;
      const metadataFullName = readMetadataString(metadata, "full_name") ?? "";
      const metadataOrgName = readMetadataString(metadata, "invited_org_name", "organization_name");
      const metadataRole = readMetadataString(metadata, "invited_role", "role");
      const inviterId = readMetadataString(metadata, "invited_by_user_id");
      const metadataInvitedBy = readMetadataString(metadata, "invited_by_name");
      const hasInvitationContext = Boolean(
        metadataOrgName
        || metadataRole
        || readMetadataString(metadata, "invited_org_id", "organization_id", "invitation_token")
      );
      if (!hasInvitationContext) {
        return false;
      }

      let inviterName = metadataInvitedBy;
      if (!inviterName && inviterId) {
        const { data: inviterProfile } = await supabase
          .from("profiles")
          .select("full_name")
          .eq("id", inviterId)
          .maybeSingle();
        inviterName = inviterProfile?.full_name || null;
      }

      setInvitationEmail(fallbackUser.email ?? null);
      setInvitationOrgName(metadataOrgName);
      setInvitedByName(inviterName);
      setInvitedRole(metadataRole);
      setIsInvitationSession(true);
      setEmail(fallbackUser.email ?? "");
      if (metadataOrgName) {
        setOrganizationName(metadataOrgName);
      }
      if (metadataFullName) {
        setFullName(metadataFullName);
      }
      return true;
    } finally {
      setIsInviteContextLoading(false);
    }
  },
  []
);

