useEffect(() => {
    let cancelled = false;
    const hashType = getAuthCallbackType(location.hash);
    const isRecoveryCallback = hashType === "recovery" || recoveryParam;

    if (isRecoveryCallback) {
      void (async () => {
        try {
          await establishRecoverySession();
          if (cancelled) {
            return;
          }
          setError(null);
          setView("setNewPassword");
          clearAuthCallbackState();
        } catch (recoveryError) {
          if (cancelled) {
            return;
          }
          setView("signIn");
          setError((recoveryError as Error).message);
        }
      })();
    }

    const isInviteCallback =
      !isRecoveryCallback && (hashType === "invite" || hashType === "signup");

    if (isInviteCallback && inviteTokenParam) {
      setIsInvitationSession(true);
      setView("acceptInvitation");
    }
    if (isInviteCallback) {
      void (async () => {
        const hasInviteContext = await hydrateInviteContext();
        if (hasInviteContext) {
          setView("acceptInvitation");
        }
      })();
    }

    // Also listen via onAuthStateChange for PASSWORD_RECOVERY and invite event
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === "PASSWORD_RECOVERY") {
        setView("setNewPassword");
        clearAuthCallbackState();
      }
      if ((event === "SIGNED_IN" || event === "INITIAL_SESSION") && isInviteCallback && session?.user) {
        void (async () => {
          const hasInviteContext = await hydrateInviteContext(session.user);
          if (hasInviteContext) {
            setView("acceptInvitation");
          }
          clearAuthCallbackState();
        })();
      }
    });

    return () => {
      cancelled = true;
      subscription.unsubscribe();
    };
  }, [clearAuthCallbackState, establishRecoverySession, hydrateInviteContext, inviteTokenParam, location.hash, recoveryParam])

