useEffect(() => {
    let isActive = true;

    const loadTerms = async () => {
      setIsLoading(true);

      const { data, error: requestError } = await supabase
        .from("legal_document_versions")
        .select("id, document_key, version, title, body_markdown, summary_bullets, effective_at")
        .eq("document_key", TERMS_DOCUMENT_KEY)
        .eq("is_active", true)
        .order("effective_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (!isActive) {
        return;
      }

      if (requestError) {
        console.error("Error loading legal terms:", requestError);
        setDocument(getFallbackTermsDocument());
        setIsLoading(false);
        return;
      }

      const nextDocument = normalizeLegalDocument(data);
      if (!nextDocument) {
        setDocument(getFallbackTermsDocument());
        setIsLoading(false);
        return;
      }

      setDocument(nextDocument);
      setIsLoading(false);
    };

