useCallback(async () => {
    const { data: initialSessionData } = await supabase.auth.getSession();
    if (!initialSessionData.session) throw new Error("Not authenticated");

    const now = Math.floor(Date.now() / 1000);
    const expiresAt = initialSessionData.session.expires_at ?? 0;
    const shouldRefresh = expiresAt - now < 60;
    const { data: refreshedData } = shouldRefresh
      ? await supabase.auth.refreshSession()
      : { data: initialSessionData };
    const activeSession = refreshedData.session ?? initialSessionData.session;

    if (!activeSession?.access_token) {
      throw new Error("Session expired. Please sign in again.");
    }

    return activeSession.access_token;
  }, [])

