useMemo(() => {
    return items?.filter((item) => {
      // Real-time fuzzy search: all typed words must match at least one visible field
      let matchesSearch = true;
      if (search.trim()) {
        const searchWords = search.trim().toLowerCase().split(/\s+/);
        const statusText = item.amount === 0
          ? "out of stock"
          : isLowStock(item, activeThresholds)
            ? "low stock"
            : isOverstock(item)
              ? "overstock"
              : "in stock";
        const searchableText = [
          item.item_code,
          item.vendors?.name || "",
          item.vendor_code || "",
          item.description,
          item.category || "",
          item.abc_curve,
          statusText,
          String(item.amount),
          String(item.initial_quantity ?? ""),
          String(item.optimal_inventory),
          (item.amount * item.unit_value).toFixed(2),
        ].join(" ").toLowerCase();
        matchesSearch = searchWords.every((word) => searchableText.includes(word));
      }

      // Category filter
      const matchesCategory = !categoryFilter || categoryFilter === "all" || item.category === categoryFilter;

      // ABC filter
      const matchesABC = !abcFilter || abcFilter === "all" || item.abc_curve === abcFilter;

      // Stock filter
      let matchesStock = true;
      if (stockFilter === "low") {
        matchesStock = isLowStock(item, activeThresholds);
      } else if (stockFilter === "out") {
        matchesStock = item.amount === 0;
      } else if (stockFilter === "overstock") {
        matchesStock = isOverstock(item);
      } else if (stockFilter === "ok") {
        matchesStock = item.amount > 0 && !isLowStock(item, activeThresholds) && !isOverstock(item);
      }

      return matchesSearch && matchesCategory && matchesABC && matchesStock;
    });
  }, [items, search, categoryFilter, abcFilter, stockFilter, activeThresholds])

