      <!DOCTYPE html>
      <html>
        <head>
          <title>Print QR Codes</title>
          <style>
            * { box-sizing: border-box; }
            body {
              margin: 0;
              padding: 0;
              font-family: Arial, sans-serif;
              color: #111827;
              width: ${format.sheet.width}${u};
            }
            .grid {
              display: grid;
              grid-template-columns: repeat(${format.grid.columns}, ${format.label.width}${u});
              grid-auto-rows: ${format.label.height}${u};
              column-gap: ${format.gap.horizontal}${u};
              row-gap: ${format.gap.vertical}${u};
              padding-top: ${format.margins.top}${u};
              padding-bottom: ${format.margins.bottom}${u};
              padding-left: ${format.margins.left}${u};
              padding-right: ${format.margins.right}${u};
              justify-content: start;
            }
            .label {
              display: flex;
              flex-direction: row;
              align-items: center;
              justify-content: flex-start; /* QR on the left */
              page-break-inside: avoid;
              width: ${format.label.width}${u};
              height: ${format.label.height}${u};
              padding: 2mm;
              overflow: hidden;
              gap: ${gapSize};
            }
            .label img.qr {
              width: auto;
              height: ${qrHeight}; /* Use more vertical area */
              max-width: ${qrMaxWidth}; /* Prevent it from overtaking the text too much */
              max-height: 40mm;
              object-fit: contain;
              flex-shrink: 0;
            }
            .info {
              display: flex;
              flex-direction: column;
              align-items: center;
              justify-content: center;
              flex: 1;
              min-width: 0;
            }
            .code {
              font-size: ${codeFontSize};
              font-weight: 700;
              color: #111827;
              line-height: 1.2;
              margin-bottom: 1.5mm;
              text-align: center;
              word-break: break-word;
            }
            .name {
              font-size: ${nameFontSize};
              color: #4b5563;
              line-height: 1.2;
              text-align: center;
              word-break: break-word;
              display: -webkit-box;
              -webkit-line-clamp: ${nameLineClamp};
              -webkit-box-orient: vertical;
              overflow: hidden;
            }
            @page {
              size: ${format.sheet.width}${u} ${format.sheet.height}${u};
              margin: 0;
            }
          </style>
        </head>
        <body>
          <div class="grid">${cards}</div>
          <script>
            window.onload = function () {
              window.print();
              setTimeout(function () { window.close(); }, 100);
            };
          </script>
        </body>
      </html>
    `)

