useEffect(() => {
    if (!isSuccessRedirect || !user) return;
    setIsSuccess(true);

    const sessionId = searchParams.get("session_id");
    let cancelled = false;

    // ── Primary path: call sync-checkout-session for instant activation ──
    async function syncAndRedirect() {
      if (sessionId) {
        try {
          const { data, error } = await supabase.functions.invoke("sync-checkout-session", {
            body: { sessionId },
          });

          if (!error && data?.success && !cancelled) {
            await refreshProfile();
            navigate("/");
            return; // Done — no need to poll
          }

          if (!cancelled) {
            console.warn("sync-checkout-session did not succeed, falling back to polling:", error || data);
          }
        } catch (err) {
          if (!cancelled) {
            console.warn("sync-checkout-session call failed, falling back to polling:", err);
          }
        }
      }

      // ── Fallback path: poll the database for webhook-driven activation ──
      if (cancelled) return;

      const pollInterval = setInterval(async () => {
        if (cancelled) { clearInterval(pollInterval); return; }
        try {
          const { data, error } = await supabase
            .from("organizations")
            .select("subscription_status")
            .single();

          if (!error && (data?.subscription_status === "active" || data?.subscription_status === "trialing")) {
            clearInterval(pollInterval);
            if (!cancelled) {
              await refreshProfile();
              navigate("/");
            }
          }
        } catch (e) {
          console.error("Polling error:", e);
        }
      }, 2000);

      // Hard timeout: redirect after 15s regardless
      const fallbackTimer = setTimeout(async () => {
        clearInterval(pollInterval);
        if (!cancelled) {
          await refreshProfile();
          navigate("/");
        }
      }, 15000);

      // Store for cleanup
      cleanupRef.pollInterval = pollInterval;
      cleanupRef.fallbackTimer = fallbackTimer;
    }

    const cleanupRef: { pollInterval?: ReturnType<typeof setInterval>; fallbackTimer?: ReturnType<typeof setTimeout> } = {};
    syncAndRedirect();

    return () => {
      cancelled = true;
      if (cleanupRef.pollInterval) clearInterval(cleanupRef.pollInterval);
      if (cleanupRef.fallbackTimer) clearTimeout(cleanupRef.fallbackTimer);
    };
  }, [isSuccessRedirect, navigate, user, refreshProfile, searchParams])

