useCallback(() => {
    const element = scrollContainerRef.current;

    if (!element) {
      setHasReachedEnd(false);
      setScrollProgress(0);
      return;
    }

    const maxScrollTop = element.scrollHeight - element.clientHeight;

    if (maxScrollTop <= 8) {
      setHasReachedEnd(true);
      setScrollProgress(100);
      return;
    }

    const nextProgress = Math.min(100, Math.round((element.scrollTop / maxScrollTop) * 100));
    const reachedBottom = element.scrollTop >= maxScrollTop - 8;

    setScrollProgress(nextProgress);
    setHasReachedEnd(reachedBottom);
  }, [])

