text:
plans.map((plan, i) => {
            const cardDelay = i * 20;
            const cardOpacity = interpolate(
              frame,
              [cardDelay, cardDelay + 40],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );
            const cardY = interpolate(
              frame,
              [cardDelay, cardDelay + 40],
              [50, 0],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            return (
              <div
                key={i}
                style={{
                  width: 320,
                  backgroundColor: COLORS.card,
                  borderRadius: 20,
                  padding: 32,
                  border: `2px solid ${plan.popular ? plan.color : "transparent"}`,
                  transform: `translateY(${cardY}px)`,
                  opacity: cardOpacity,
                  position: "relative",
                }}
              >
                {/* Popular badge */}
                {plan.popular && (
                  <div
                    style={{
                      position: "absolute",
                      top: -12,
                      left: "50%",
                      transform: "translateX(-50%)",
                      padding: "6px 16px",
                      backgroundColor: plan.color,
                      borderRadius: 20,
                      fontSize: 12,
                      fontWeight: "bold",
                      color: COLORS.text,
                      fontFamily: "Inter, sans-serif",
                    }}
                  >
                    Most Popular
                  </div>
                )}

                <div
                  style={{
                    fontSize: 24,
                    fontWeight: "bold",
                    color: COLORS.text,
                    fontFamily: "Inter, sans-serif",
                    marginBottom: 8,
                  }}
                >
                  {plan.name}
                </div>

                <div
                  style={{
                    display: "flex",
                    alignItems: "baseline",
                    marginBottom: 24,
                  }}
                >
                  <span
                    style={{
                      fontSize: 48,
                      fontWeight: "bold",
                      color: plan.popular ? plan.color : COLORS.text,
                      fontFamily: "Inter, sans-serif",
                    }}
                  >
                    {plan.price}
                  </span>
                  <span
                    style={{
                      fontSize: 16,
                      color: COLORS.textMuted,
                      marginLeft: 4,
                      fontFamily: "Inter, sans-serif",
                    }}
                  >
                    /mo
                  </span>
                </div>

                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    gap: 12,
                  }}
                >
                  {[
                    { icon: "👥", label: `${plan.users} users` },
                    { icon: "📦", label: `${plan.items} items` },
                    { icon: "∞", label: "Unlimited transactions" },
                    { icon: "📊", label: "Export reports" },
                    { icon: "🔒", label: "Data encryption" },
                  ].map((feature, j) => (
                    <div
                      key={j}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 12,
                      }}
                    >
                      <span style={{ fontSize: 16 }}>{feature.icon}</span>
                      <span
                        style={{
                          fontSize: 14,
                          color: COLORS.text,
                          fontFamily: "Inter, sans-serif",
                        }}
                      >
                        {feature.label}
                      </span>
                    </div>
                  ))}
                </div>

                <div
                  style={{
                    marginTop: 30,
                    padding: "14px 24px",
                    backgroundColor: plan.popular ? plan.color : "transparent",
                    borderRadius: 8,
                    border: `2px solid ${plan.popular ? plan.color : COLORS.textMuted}`,
                    textAlign: "center",
                  }}
                >
                  <span
                    style={{
                      fontSize: 16,
                      fontWeight: "bold",
                      color: plan.popular ? COLORS.text : COLORS.text,
                      fontFamily: "Inter, sans-serif",
                    }}
                  >
                    Get Started
                  </span>
                </div>
              </div>
            );
          })

