useEffect(() => {
    let isActive = true;

    if (!userId) {
      lastCheckedUserIdRef.current = null;
      setSubStatus("checking");
      return;
    }

    if (requiresInvitationCompletion) {
      lastCheckedUserIdRef.current = userId;
      setSubStatus("active");
      return;
    }

    // The subscription page must always remain reachable for upgrades.
    if (location.pathname === "/subscribe" || isTermsAcceptanceRoute) {
      lastCheckedUserIdRef.current = userId;
      setSubStatus("active");
      return;
    }

    // Only reset to checking on identity changes.
    // For same-user background checks, keep current route mounted.
    if (lastCheckedUserIdRef.current !== userId) {
      setSubStatus("checking");
    }

    supabase
      .rpc("get_effective_plan")
      .then(({ data, error }) => {
        if (!isActive) return;
        lastCheckedUserIdRef.current = userId;

        if (error) {
          console.error("Error checking subscription:", error);
          // On error, fall back to "active" so we don't lock users out on DB errors
          setSubStatus("active");
          return;
        }
        const plan = data as string;
        if (ACTIVE_PLANS.includes(plan)) {
          setSubStatus("active");
        } else if (plan === "pending") {
          setSubStatus("pending");
        } else {
          // 'expired'
          setSubStatus("expired");
        }
      });

    return () => {
      isActive = false;
    };
  }, [userId, location.pathname, requiresInvitationCompletion, isTermsAcceptanceRoute])

