    const refreshItemLimit = async () => {
      try {
        const snapshot = await getPlanLimitsSnapshot();
        const reached = isItemLimitReached(snapshot);
        setItemLimitReached(reached);
        if (reached) {
          setItemLimitMessage(
            `Plan item limit reached (${snapshot.currentItems}/${snapshot.maxItems}). Upgrade your plan to add more items.`
          );
        } else {
          setItemLimitMessage(null);
        }
      } catch {
        setItemLimitReached(false);
        setItemLimitMessage(null);
      }
    };

    refreshItemLimit();
  }, [items?.length])

