text:
useCallback(
    async (code: string) => {
      const now = Date.now();
      if (
        lastScanRef.current &&
        lastScanRef.current.code === code &&
        now - lastScanRef.current.time < SCAN_COOLDOWN_MS
      ) {
        return;
      }
      lastScanRef.current = { code, time: now };

      const parsed = parseQRCode(code);
      const validation = validateQRForStep(parsed, "items");
      if (!validation.valid) {
        playErrorBeep();
        toast.error(validation.error);
        return;
      }

      const lookupValue = parsed.value;
      setIsProcessing(true);

      const scanStartTime = Date.now();
      try {
        const item = await lookupItem.mutateAsync(lookupValue);

        if (mode === "checkout") {
          if (item.amount <= 0) {
            playErrorBeep();
            toast.error("Item out of stock!");
            trackScanFailed({ errorType: "out_of_stock", scanType: modeToScanType(mode) });
            return;
          }

          const didAdd = addOrIncrementScannedItem(item);
          if (!didAdd) return;
        } else {
          setScannedItem(item);
          setQuantity(1);
        }

        playSuccessBeep();
        toast.success(`Item found: ${item.description}`);
        trackScanSuccess({
          scanType: modeToScanType(mode),
          itemCount: 1,
          scanDurationMs: Date.now() - scanStartTime,
        });
      } catch {
        playErrorBeep();
        toast.error(
          `Code ${lookupValue} not found in the registry. Please check if the item is registered.`
        );
        trackScanFailed({ errorType: "not_found", scanType: modeToScanType(mode) });
      } finally {
        setIsProcessing(false);
      }
    },
    [lookupItem, mode, addOrIncrementScannedItem]
  )

