text:
useCallback((file: File) => {
    setUploadError(null);
    const ext = file.name.split(".").pop()?.toLowerCase();
    if (!["csv", "xlsx", "xls"].includes(ext ?? "")) {
      setUploadError("Only CSV, XLSX, and XLS files are supported.");
      return;
    }

    const reader = new FileReader();

    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        let json: RawRow[];
        let hdrs: string[];

        if (ext === "csv") {
          // ── CSV: use inline parser ──────────────────────────────────────
          const rows = parseCSVText(data as string);
          if (rows.length === 0) { setUploadError("The file appears to be empty."); return; }
          hdrs = Object.keys(rows[0]);
          json = rows;
        } else {
          // ── XLSX/XLS: use ExcelJS ──────────────────────────────────────
          const workbook = new ExcelJS.Workbook();
          await workbook.xlsx.load(data as ArrayBuffer);

          const worksheet = workbook.worksheets[0];
          if (!worksheet) { setUploadError("The file appears to be empty."); return; }

          // Extract headers from row 1
          hdrs = [];
          worksheet.getRow(1).eachCell({ includeEmpty: false }, (cell, colIndex) => {
            hdrs[colIndex - 1] = String(cell.value ?? "");
          });
          hdrs = hdrs.filter(Boolean);

          // Extract data rows
          json = [];
          worksheet.eachRow((row, rowNumber) => {
            if (rowNumber === 1) return;
            const obj: RawRow = {};
            row.eachCell({ includeEmpty: true }, (cell, colIndex) => {
              const header = hdrs[colIndex - 1];
              if (!header) return;
              const val = cell.value;
              if (val === null || val === undefined) {
                obj[header] = null;
              } else if (typeof val === "object" && "result" in val) {
                // Formula cell — use its computed result
                obj[header] = (val as ExcelJS.CellFormulaValue).result as string | number;
              } else if (typeof val === "object" && "richText" in val) {
                // Rich text cell
                obj[header] = (val as ExcelJS.CellRichTextValue).richText?.map((r) => r.text).join("") ?? null;
              } else if (val instanceof Date) {
                obj[header] = val.toISOString();
              } else {
                obj[header] = val as string | number;
              }
            });
            if (Object.values(obj).some((v) => v !== null)) json.push(obj);
          });
        }

        if (json.length === 0) { setUploadError("The file appears to be empty."); return; }

        setHeaders(hdrs);
        setRawRows(json);
        setFileName(file.name);
        setMapping(autoDetectMapping(hdrs));
        setStep("map");
      } catch {
        setUploadError("Could not read the file. Please make sure it's a valid CSV or Excel file.");
      }
    };

    if (ext === "csv") {
      reader.readAsText(file);
    } else {
      reader.readAsArrayBuffer(file);
    }
  }, [])

