useEffect(() => {
    // onAuthStateChange fires the INITIAL_SESSION event on mount with the
    // current session — this replaces the separate getSession() call and
    // prevents the double fetchProfile() that was happening on every page load.
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event, nextSession) => {
      setSession(nextSession);

      const nextUser = nextSession?.user ?? null;
      setUser((currentUser) => {
        // Token refresh can emit a new user object with the same id.
        // Keep identity stable so route guards don't remount the app shell.
        if (
          event === "TOKEN_REFRESHED" &&
          currentUser &&
          nextUser &&
          currentUser.id === nextUser.id
        ) {
          return currentUser;
        }
        return nextUser;
      });

      if (nextUser) {
        if (event === "TOKEN_REFRESHED") {
          setIsLoading(false);
          return;
        }
        setTermsStatus((current) => ({
          ...current,
          isLoading: true,
          error: null,
        }));
        fetchProfile(nextUser.id, nextUser.email ?? null);
      } else {
        setProfile(null);
        setTermsStatus(createDefaultTermsStatus());
        setOrganizationName(null);
        setRequiresInvitationCompletion(false);
        setPendingInvitationToken(null);
        setIsLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, [])

