useCallback(async () => {
    const { data: documentRow, error: documentError } = await supabase
      .from("legal_document_versions")
      .select("id, document_key, version, title, body_markdown, summary_bullets, effective_at")
      .eq("document_key", TERMS_DOCUMENT_KEY)
      .eq("is_active", true)
      .order("effective_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (documentError) {
      throw documentError;
    }

    if (!documentRow) {
      return normalizeTermsStatus(null);
