    const { data: acceptanceRow, error: acceptanceError } = await supabase
      .from("user_legal_acceptances")
      .select("accepted_at")
      .eq("document_version_id", documentRow.id)
      .order("accepted_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (acceptanceError) {
      throw acceptanceError;
    }

    return normalizeTermsStatus({
      ...documentRow,
      accepted_at: acceptanceRow?.accepted_at ?? null,
    });
  }, [])

