useCallback(async () => {
    setTermsStatus((current) => ({
      ...current,
      isLoading: true,
      error: null,
    }));

    try {
      const { data, error } = await supabase.rpc("get_required_terms_status");

      if (error) {
        throw error;
      }

      const statusRow = Array.isArray(data) ? data[0] : data;
      let normalizedStatus = normalizeTermsStatus(statusRow ?? null);

      if (normalizedStatus.source === "fallback" && !isLocalTermsFallbackEnabled()) {
        normalizedStatus = await fetchTermsStatusDirect();
      }

      if (normalizedStatus.source === "fallback" && !isLocalTermsFallbackEnabled()) {
        throw new Error("The active Terms and Conditions could not be loaded from the server.");
      }

      setTermsStatus({
        ...normalizedStatus,
        isLoading: false,
        error: null,
      });
    } catch (error) {
      console.error("Error fetching legal terms status:", error);

      try {
        const directStatus = await fetchTermsStatusDirect();

        if (directStatus.source !== "fallback" || isLocalTermsFallbackEnabled()) {
          setTermsStatus({
            ...directStatus,
            isLoading: false,
            error: null,
          });
          return;
        }
      } catch (directError) {
        console.error("Error fetching legal terms status directly:", directError);
      }

      if (isLocalTermsFallbackEnabled()) {
        const fallbackStatus = getFallbackTermsStatus();
        setTermsStatus({
          ...fallbackStatus,
          isLoading: false,
          error: null,
        });
        return;
      }

      setTermsStatus({
        isLoading: false,
        needsAcceptance: true,
        acceptedAt: null,
        document: null,
        source: "remote",
        error: "We could not verify your Terms and Conditions status right now. Please retry in a moment. If the problem continues, the server-side legal terms setup may be missing.",
      });
    }
  }, [fetchTermsStatusDirect])

