text:
Deno.serve(async (req) => {
  const origin = req.headers.get("origin");
  const corsHeaders = buildCorsHeaders(origin);

  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({
        success: false,
        code: "unauthorized",
        error: "Missing authorization header",
      }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const jwtMatch = authHeader.match(/^Bearer\s+(.+)$/i);
    const accessToken = jwtMatch ? jwtMatch[1].trim() : authHeader;

    const userClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } } }
    );

    const adminClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    const { data: authData, error: authError } = await userClient.auth.getUser(accessToken);
    if (authError || !authData.user) {
      return new Response(JSON.stringify({
        success: false,
        code: "unauthorized",
        error: "Unauthorized",
      }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { targetUserId } = await req.json() as { targetUserId?: string };
    if (!targetUserId) {
      return new Response(JSON.stringify({ error: "targetUserId is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (targetUserId === authData.user.id) {
      return new Response(JSON.stringify({ error: "You cannot remove your own account" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { data: actorProfile, error: actorProfileError } = await userClient
      .from("profiles")
      .select("organization_id, role")
      .eq("id", authData.user.id)
      .single();

    if (actorProfileError || !actorProfile) {
      return new Response(JSON.stringify({ error: "Could not load your profile" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (actorProfile.role !== "master_admin") {
      return new Response(JSON.stringify({ error: "Only master admins can remove users" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { data: targetProfile, error: targetProfileError } = await adminClient
      .from("profiles")
      .select("id, organization_id")
      .eq("id", targetUserId)
      .single();

    if (targetProfileError || !targetProfile) {
      return new Response(JSON.stringify({ error: "User not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (targetProfile.organization_id !== actorProfile.organization_id) {
      return new Response(JSON.stringify({ error: "Cannot remove users outside your organization" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { data: targetAuthUserData, error: targetAuthUserError } = await adminClient.auth.admin.getUserById(targetUserId);
    if (targetAuthUserError || !targetAuthUserData.user) {
      return new Response(JSON.stringify({ error: "User auth record not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const targetEmail = targetAuthUserData.user.email ?? null;

    // Cleanup invitation rows for that email in the same organization.
    if (targetEmail) {
      await adminClient
        .from("organization_invitations")
        .delete()
        .eq("organization_id", actorProfile.organization_id)
        .eq("email", targetEmail);
    }

    const { error: deleteAuthError } = await adminClient.auth.admin.deleteUser(targetUserId);
    if (deleteAuthError) {
      return new Response(JSON.stringify({ error: deleteAuthError.message }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    await captureServerEvent({
      event: "user_removed",
      distinctId: authData.user.id,
      actorUserId: authData.user.id,
      organizationId: actorProfile.organization_id,
      functionName: "delete-user",
      dedupeKey: `delete-user:${targetUserId}:user_removed`,
      properties: {
        targetUserId,
      },
    });

    return new Response(JSON.stringify({ success: true, removedUserId: targetUserId, removedEmail: targetEmail }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (error) {
    return new Response(JSON.stringify({ error: (error as Error).message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
})

