Deno.serve(async (request: Request) => {
  const corsHeaders = buildCorsHeaders(request.headers.get("origin"));

  if (request.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  if (request.method !== "POST") {
    return jsonResponse({ ok: false, error: "Method not allowed." }, corsHeaders, 405);
  }

  let body: Record<string, unknown>;
  try {
    body = await request.json();
  } catch {
    return jsonResponse({ ok: false, error: "Invalid JSON." }, corsHeaders, 400);
  }

  // ── Validation ───────────────────────────────────────────────────────────
  const name = typeof body.name === "string" ? body.name.trim() : "";
  const email = typeof body.email === "string" ? body.email.trim() : "";
  const company = typeof body.company === "string" ? body.company.trim() : "";
  const message = typeof body.message === "string" ? body.message.trim() : "";
  const website = typeof body.website === "string" ? body.website.trim() : "";
  const loadTime = typeof body.loadTime === "number" ? body.loadTime : 0;

  if (!name || name.length < 2 || name.length > 80) {
    return jsonResponse({ ok: false, error: "Invalid name." }, corsHeaders, 400);
  }
  if (!isValidEmail(email)) {
    return jsonResponse({ ok: false, error: "Invalid email." }, corsHeaders, 400);
  }
  if (company.length > 120) {
    return jsonResponse({ ok: false, error: "Company name too long." }, corsHeaders, 400);
  }
  if (!message || message.length < 10 || message.length > 4000) {
    return jsonResponse({ ok: false, error: "Invalid message." }, corsHeaders, 400);
  }

  const now = Date.now();
  const looksBotLike = Boolean(website) || now - loadTime < 3000;
  if (looksBotLike) {
    // Silently succeed to not tip off bots
    return jsonResponse({ ok: true }, corsHeaders);
  }

  const ip = getClientIp(request);
  if (isRateLimited(ip, now)) {
    return jsonResponse({ ok: false, error: "Too many messages. Try again later." }, corsHeaders, 429);
  }

  try {
    await sendWithResend({ name, email, company, message });
    return jsonResponse({ ok: true }, corsHeaders);
  } catch (error) {
    console.error("Contact send failed:", error);
    return jsonResponse({ ok: false, error: "Failed to send message." }, corsHeaders, 500);
  }
})

