    const { email, role } = (await req.json()) as {
      email: string;
      role?: InviteRole;
    };
    const normalizedEmail = email?.trim().toLowerCase();
    const normalizedRole: InviteRole = role ?? "read_only";

    if (!normalizedEmail) {
      return jsonResponse({ error: "Email is required" }, cors, 400);
    }
    if (!["admin", "user", "read_only"].includes(normalizedRole)) {
      return jsonResponse({ error: "Invalid role" }, cors, 400);
    }

