            properties: {
              role: normalizedRole,
              invitationId: invitationId ?? null,
              resent: true,
            },
          });

          return jsonResponse(
            { success: true, token, resent: true },
            cors,
          );
        }

        // Truly existing user — clean up invitation record
        if (invitationId) {
          await adminClient
            .from("organization_invitations")
            .delete()
            .eq("id", invitationId);
        }

        return jsonResponse(
          {
            success: false,
            code: "already_exists",
            error:
              "A user with this email already exists. Please use a different email address.",
          },
          cors,
          409,
        );
      }

      return jsonResponse({ error: authInviteError.message }, cors, 400);
    }

    await captureServerEvent({
      event: "invitation_sent",
      distinctId: authData.user.id,
      actorUserId: authData.user.id,
      organizationId: profile.organization_id,
      functionName: "invite-user",
