      properties: {
        role: normalizedRole,
        invitationId: invitationId ?? null,
        resent: false,
      },
    });

    return jsonResponse({ success: true, token }, cors);
  } catch (error) {
    const origin = req.headers.get("origin");
    return jsonResponse(
      { error: (error as Error).message },
      buildCorsHeaders(origin),
      500,
    );
  }
})

