Deno.serve(async (req) => {
  const origin = req.headers.get("origin");
  const cors = buildCorsHeaders(origin);

  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: cors });
  }

  if (req.method !== "POST") {
    return jsonResponse({ success: false, error: "Method not allowed" }, cors, 405);
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseAnonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return jsonResponse(
        { success: false, code: "unauthorized", error: "Missing authorization header" },
        cors,
        401,
      );
    }

    const jwtMatch = authHeader.match(/^Bearer\s+(.+)$/i);
    const accessToken = jwtMatch ? jwtMatch[1].trim() : authHeader;

    const userClient = createClient(supabaseUrl, supabaseAnonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const adminClient = createClient(supabaseUrl, supabaseServiceKey);

    const { data: authData, error: authError } = await userClient.auth.getUser(accessToken);
    const user = authData.user;

    if (authError || !user || !user.email) {
      console.error("Auth Failed:", { authError, hasUser: !!user, hasEmail: !!user?.email });
      return jsonResponse(
        { success: false, code: "unauthorized", error: "Unauthorized - please log in again", debugDetails: { authError, hasUser: !!user, hasEmail: !!user?.email } },
        cors,
        401,
      );
    }

    const body = (await req.json().catch(() => ({}))) as AcceptPlatformTermsBody;
    const documentKey = body.documentKey?.trim() || PLATFORM_TERMS_KEY;
    const acceptanceSource = body.acceptanceSource?.trim() || "web_app";

    if (documentKey !== PLATFORM_TERMS_KEY) {
      return jsonResponse(
        { success: false, code: "invalid_request", error: "Unsupported legal document key" },
        cors,
        400,
      );
    }

    const { data: document, error: documentError } = await adminClient
      .from("legal_document_versions")
      .select("id, version")
      .eq("document_key", documentKey)
      .eq("is_active", true)
      .order("effective_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (documentError) {
      console.error("Failed to load active legal document:", documentError);
      return jsonResponse(
        { success: false, code: "terms_unavailable", error: "Active terms could not be verified" },
        cors,
