Deno.serve(async (req) => {
  const origin = req.headers.get("origin");
  const cors = buildCorsHeaders(origin);

  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: cors });
  }

  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, cors, 405);
  }

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return jsonResponse(
        { success: false, code: "unauthorized", error: "Missing authorization header" },
        cors,
        401,
      );
    }

    const jwtMatch = authHeader.match(/^Bearer\s+(.+)$/i);
    const accessToken = jwtMatch ? jwtMatch[1].trim() : authHeader;

    const userClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } } },
    );
    const adminClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    const { data: authData, error: authError } = await userClient.auth.getUser(accessToken);
    if (authError || !authData.user) {
      return jsonResponse(
        { success: false, code: "unauthorized", error: "Unauthorized" },
        cors,
        401,
      );
    }

    const { targetUserId, newRole } = (await req.json()) as {
      targetUserId?: string;
      newRole?: string;
    };
    if (!targetUserId || !newRole || !isValidRole(newRole)) {
      return jsonResponse(
        { error: "targetUserId and a valid newRole are required" },
        cors,
        400,
      );
    }

    const { data: actorProfile, error: actorProfileError } = await userClient
      .from("profiles")
      .select("organization_id, role")
      .eq("id", authData.user.id)
      .single<{ organization_id: string; role: UserRole }>();

    if (actorProfileError || !actorProfile?.organization_id) {
      return jsonResponse({ error: "Could not load your profile" }, cors, 400);
    }
    if (actorProfile.role !== "master_admin") {
      return jsonResponse({ error: "Only master admins can change user roles" }, cors, 403);
    }

    const { data: targetProfile, error: targetProfileError } = await adminClient
      .from("profiles")
      .select("id, organization_id, role")
      .eq("id", targetUserId)
      .single<{ id: string; organization_id: string; role: UserRole }>();

    if (targetProfileError || !targetProfile) {
      return jsonResponse({ error: "Target user profile not found" }, cors, 404);
    }
    if (targetProfile.organization_id !== actorProfile.organization_id) {
      return jsonResponse(
        { error: "Cannot update users outside your organization" },
        cors,
        403,
      );
    }

    const previousRole = targetProfile.role;
    const { error: updateError } = await userClient.rpc("update_user_role", {
      target_user_id: targetUserId,
      new_role: newRole,
    });
    if (updateError) {
      return jsonResponse({ error: updateError.message }, cors, 400);
    }

    await captureServerEvent({
      event: "user_role_changed",
      distinctId: authData.user.id,
      actorUserId: authData.user.id,
      organizationId: actorProfile.organization_id,
      functionName: "update-user-role",
      dedupeKey: `update-user-role:${targetUserId}:${newRole}:${Date.now()}`,
      properties: {
        targetRole: newRole,
        previousRole,
        targetUserId,
      },
    });

    return jsonResponse({ success: true, targetUserId, previousRole, newRole }, cors);
  } catch (error) {
    return jsonResponse(
      { error: (error as Error).message || "Unexpected server error" },
      cors,
      500,
    );
  }
})

