Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders(req) });
  }

  if (req.method !== "POST") {
    return json(req, 405, { error: "Method not allowed" });
  }

  try {
    if (!stripe) {
      return json(req, 500, { error: "Missing STRIPE_SECRET_KEY in function secrets" });
    }

    const rawAuthHeader = req.headers.get("Authorization") ?? req.headers.get("authorization");
    const accessToken = extractBearerToken(rawAuthHeader);
    if (!accessToken) {
      return json(req, 401, { error: "Missing authorization header" });
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: `Bearer ${accessToken}` } } }
    );

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return json(req, 401, { error: "Unauthorized" });
    }

    const { data: profile, error: profileError } = await supabase
      .from("profiles")
      .select("organization_id, role")
      .eq("id", user.id)
      .single();
    if (profileError || !profile?.organization_id) {
      return json(req, 400, { error: "No organization linked to user" });
    }
    if (profile.role !== "master_admin") {
      return json(req, 403, { error: "Only master_admin can cancel subscriptions" });
    }

    const { data: existingSub, error: existingSubError } = await supabase
      .from("subscriptions")
      .select("stripe_subscription_id, stripe_schedule_id")
      .eq("organization_id", profile.organization_id)
      .order("updated_at", { ascending: false, nullsFirst: false })
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (existingSubError) throw existingSubError;
    if (!existingSub?.stripe_subscription_id) {
      return json(req, 404, { error: "No active subscription found for this organization" });
    }

    const stripeSub = await stripe.subscriptions.retrieve(existingSub.stripe_subscription_id);
    if (stripeSub.status === "canceled" || stripeSub.status === "incomplete_expired") {
      return json(req, 409, { error: "Subscription is already canceled" });
    }

    const scheduleId = extractStripeId(stripeSub.schedule) ?? existingSub.stripe_schedule_id ?? null;
    if (scheduleId) {
      await clearStripeScheduleIfPresent(stripe, scheduleId);
    }

    const effectivePlan = normalizePlanFromStripe(stripeSub);
    const updatedSub = stripeSub.cancel_at_period_end
      ? stripeSub
      : await stripe.subscriptions.update(stripeSub.id, {
          cancel_at_period_end: true,
          metadata: {
            ...stripeSub.metadata,
            organization_id: profile.organization_id,
            supabase_user_id: user.id,
            plan: effectivePlan,
          },
        });

    const { error: subUpdateError } = await supabaseAdmin
      .from("subscriptions")
      .update({
        stripe_subscription_id: updatedSub.id,
        stripe_customer_id: extractStripeId(updatedSub.customer),
        plan: effectivePlan,
        status: updatedSub.status,
        trial_ends_at: updatedSub.trial_end ? new Date(updatedSub.trial_end * 1000).toISOString() : null,
        current_period_start: new Date(updatedSub.current_period_start * 1000).toISOString(),
        current_period_end: new Date(updatedSub.current_period_end * 1000).toISOString(),
        cancel_at_period_end: true,
        pending_downgrade_plan: null,
        pending_downgrade_effective_at: null,
        stripe_schedule_id: null,
        updated_at: new Date().toISOString(),
      })
      .eq("organization_id", profile.organization_id);
    if (subUpdateError) {
      throw new Error(`Failed to persist cancellation metadata: ${subUpdateError.message}`);
    }

    const { error: orgUpdateError } = await supabaseAdmin
      .from("organizations")
      .update({
        subscription_status: normalizeOrgStatus(updatedSub.status),
        billing_owner_user_id: user.id,
        updated_at: new Date().toISOString(),
      })
      .eq("id", profile.organization_id);
    if (orgUpdateError) {
      throw new Error(`Failed to sync organization subscription state: ${orgUpdateError.message}`);
    }

    await captureServerEvent({
      event: "subscription_canceled",
      distinctId: user.id,
      actorUserId: user.id,
      organizationId: profile.organization_id,
      functionName: "cancel-subscription",
      dedupeKey: `cancel-subscription:${profile.organization_id}:${updatedSub.id}`,
      properties: {
        plan: effectivePlan,
      },
    });

    return json(req, 200, {
      success: true,
      cancelAtPeriodEnd: true,
      effectiveAt: new Date(updatedSub.current_period_end * 1000).toISOString(),
      status: updatedSub.status,
    });
  } catch (error) {
    console.error("cancel-subscription error:", error);
    return json(req, 500, { error: (error as Error).message });
  }
})

