text:
Deno.serve(async (req) => {
  const origin = req.headers.get("origin");
  const cors = buildCorsHeaders(origin);

  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: cors });
  }
  if (req.method !== "POST") {
    return jsonResponse({ success: false, error: "Method not allowed" }, cors, 405);
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseAnonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return jsonResponse(
        { success: false, code: "unauthorized", error: "Missing authorization header" },
        cors,
        401,
      );
    }

    const jwtMatch = authHeader.match(/^Bearer\s+(.+)$/i);
    const accessToken = jwtMatch ? jwtMatch[1].trim() : authHeader;

    const userClient = createClient(supabaseUrl, supabaseAnonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const adminClient = createClient(supabaseUrl, supabaseServiceKey);

    // 1. Authenticate user
    const { data: userData, error: userError } = await userClient.auth.getUser(accessToken);
    const user = userData.user;

    if (userError || !user || !user.email) {
      return jsonResponse(
        { success: false, code: "unauthorized", error: "Unauthorized - please log in again" },
        cors,
        401,
      );
    }

    // 2. Parse request body
    const body = (await req.json().catch(() => ({}))) as {
      token?: string;
      fullName?: string;
      preview?: boolean;
    };
    const token = body.token?.trim() || user.user_metadata?.invitation_token;
    const fullName = body.fullName?.trim() || null;
    const previewOnly = body.preview === true;

    if (!token) {
      return jsonResponse(
        { success: false, code: "invalid_request", error: "Invitation token is required" },
        cors,
        400,
      );
    }

    // 3. Look up invitation
    const { data: invitation, error: invitationError } = await adminClient
      .from("organization_invitations")
      .select(
        "id, organization_id, email, role, status, expires_at, invited_by, organizations(name)",
      )
      .eq("token", token)
      .single();

    if (invitationError || !invitation) {
      return jsonResponse(
        { success: false, code: "not_found", error: "Invitation not found" },
        cors,
        404,
      );
    }

    // 4. Validate email match
    if (invitation.email.toLowerCase() !== user.email.toLowerCase()) {
      return jsonResponse(
        {
          success: false,
          code: "forbidden",
          error: "This invitation does not match your account email",
        },
        cors,
        403,
      );
    }

    // 5. Check expiration
    if (
      invitation.status === "expired" ||
      (invitation.status === "pending" &&
        new Date(invitation.expires_at) < new Date())
    ) {
      return jsonResponse(
        { success: false, code: "expired", error: "This invitation has expired" },
        cors,
        410,
      );
    }

    const invitationRole: InviteRole = isValidRole(invitation.role)
      ? invitation.role
      : "read_only";
    const organizationName =
      (invitation.organizations as { name?: string } | null)?.name ??
      "Unknown Organization";

    // Resolve inviter name
    let invitedByName = "Organization Admin";
    if (invitation.invited_by) {
      const { data: inviterProfile } = await adminClient
        .from("profiles")
        .select("full_name")
        .eq("id", invitation.invited_by)
        .maybeSingle();
      if (inviterProfile?.full_name?.trim()) {
        invitedByName = inviterProfile.full_name.trim();
      }
    }

    // 6. Preview mode — return invitation details without accepting
    if (previewOnly) {
      return jsonResponse(
        {
          success: true,
          invitation: {
            id: invitation.id,
            email: invitation.email,
            role: invitationRole,
            status: invitation.status,
            organizationName,
            organizationId: invitation.organization_id,
            invitedByName,
          },
        },
        cors,
      );
    }

    // 7. Accept flow — fullName is required
    const resolvedFullName = fullName || null;
    if (!resolvedFullName) {
      return jsonResponse(
        {
          success: false,
          code: "invalid_request",
          error: "Full name is required to complete invitation",
        },
        cors,
