Deno.serve(async (req) => {
  // Handle CORS preflight
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders(req) });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...corsHeaders(req), "Content-Type": "application/json" },
    });
  }

  try {
    if (!stripe) {
      return new Response(JSON.stringify({ error: "Missing STRIPE_SECRET_KEY in function secrets" }), {
        status: 500,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    // ── Authenticate the user via Supabase JWT ──────────────────────────────
    const rawAuthHeader = req.headers.get("Authorization") ?? req.headers.get("authorization");
    const accessToken = extractBearerToken(rawAuthHeader);
    if (!accessToken) {
      return new Response(JSON.stringify({ error: "Missing authorization header" }), {
        status: 401,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: `Bearer ${accessToken}` } } }
    );

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    // ── Parse request body ──────────────────────────────────────────────────
    const body = await req.json().catch(() => null) as {
      plan?: string;
      interval?: "month" | "year";
      successUrl?: string;
      cancelUrl?: string;
    } | null;
    const plan = body?.plan as PlanKey | undefined;
    const interval = body?.interval === "year" ? "year" : "month";
    const isValidPlan = !!plan && ["starter", "business", "enterprise"].includes(plan);

    if (!isValidPlan || !plan) {
      return new Response(JSON.stringify({ error: `Unknown plan: ${plan}` }), {
        status: 400,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const priceIdsMap = interval === "year" ? ANNUAL_PRICE_IDS : MONTHLY_PRICE_IDS;
    const envMap = interval === "year" ? ANNUAL_PRICE_ENV_BY_PLAN : MONTHLY_PRICE_ENV_BY_PLAN;

    const selectedPriceId = priceIdsMap[plan];
    if (!selectedPriceId) {
      return new Response(
        JSON.stringify({
          error: `Missing ${envMap[plan]} in function secrets for plan '${plan}' (${interval})`,
        }),
        {
          status: 500,
          headers: { ...corsHeaders(req), "Content-Type": "application/json" },
        }
      );
    }
    await ensureStripePriceMatchesPlan(stripe, plan, selectedPriceId, interval);

    // ── Fetch organization info ─────────────────────────────────────────────
    const { data: profile, error: profileError } = await supabase
      .from("profiles")
      .select("organization_id, role")
      .eq("id", user.id)
      .single();
    if (profileError || !profile?.organization_id) {
      return new Response(JSON.stringify({ error: "No organization linked to user" }), {
        status: 400,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const { data: org, error: orgError } = await supabase
      .from("organizations")
      .select("id, name, subscription_status, billing_owner_user_id")
      .eq("id", profile?.organization_id)
      .single();
    if (orgError || !org?.id) {
      return new Response(JSON.stringify({ error: "Organization not found" }), {
        status: 400,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const isMasterAdmin = profile.role === "master_admin";
    const isBillingOwnerResubscribe =
      profile.role === "read_only" &&
      org.billing_owner_user_id === user.id &&
      (org.subscription_status === "canceled" || org.subscription_status === "expired");

    if (!isMasterAdmin && !isBillingOwnerResubscribe) {
      return new Response(
        JSON.stringify({
          error: "Only master_admin can manage subscriptions. Billing owner re-subscribe is only allowed after cancellation/expiry.",
        }),
        {
          status: 403,
          headers: { ...corsHeaders(req), "Content-Type": "application/json" },
        }
      );
    }

    // ── Check for existing Stripe customer ──────────────────────────────────
    const { data: existingSub } = await supabase
      .from("subscriptions")
      .select("stripe_customer_id")
      .eq("organization_id", org.id)
      .maybeSingle();

    let customerId = existingSub?.stripe_customer_id;

    if (!customerId) {
      // Create a new Stripe customer tied to this organization
      const customer = await stripe.customers.create({
        email: user.email,
        name: org.name || user.email || "Organization",
        metadata: {
          organization_id: org.id,
          supabase_user_id: user.id,
        },
      });
      customerId = customer.id;
    }

    // ── Build line items ────────────────────────────────────────────────────
    const lineItems: Stripe.Checkout.SessionCreateParams.LineItem[] = [
      { price: selectedPriceId, quantity: 1 },
    ];

    const appBaseUrl = resolveAppBaseUrl(req);
    const successUrlBase = resolveReturnUrl(body?.successUrl, appBaseUrl, "/subscribe?success=true");
    const successUrl = appendCheckoutSessionIdPlaceholder(successUrlBase);
    const cancelUrl = resolveReturnUrl(body?.cancelUrl, appBaseUrl, "/subscribe?canceled=true");

    // ── Create Stripe Checkout Session ──────────────────────────────────────
    const session = await stripe.checkout.sessions.create({
      customer: customerId,
      mode: "subscription",
      line_items: lineItems,
      success_url: successUrl,
      cancel_url: cancelUrl,
      allow_promotion_codes: true,
      subscription_data: {
        metadata: {
          organization_id: org.id,
          supabase_user_id: user.id,
          plan: plan,
        },
      },
      metadata: {
        organization_id: org.id,
        supabase_user_id: user.id,
        plan: plan,
      },
    });

    return new Response(JSON.stringify({ url: session.url, sessionId: session.id }), {
      headers: { ...corsHeaders(req), "Content-Type": "application/json" },
    });

  } catch (error) {
    console.error("create-checkout-session error:", error);
    return new Response(JSON.stringify({ error: (error as Error).message }), {
      status: 500,
      headers: { ...corsHeaders(req), "Content-Type": "application/json" },
    });
  }
})

