Deno.serve(async (request: Request) => {
  const corsHeaders = buildCorsHeaders(request.headers.get("origin"));

  if (request.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  if (request.method !== "POST") {
    return jsonResponse({ ok: false, error: "Method not allowed." }, corsHeaders, 405);
  }

  let body: Record<string, unknown>;
  try {
    body = await request.json();
  } catch {
    return jsonResponse({ ok: false, error: "Invalid JSON." }, corsHeaders, 400);
  }

  const authHeader = request.headers.get("Authorization") ?? "";
  if (!authHeader.startsWith("Bearer ")) {
    return jsonResponse({ ok: false, error: "Unauthorized." }, corsHeaders, 401);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const supabase = createClient(supabaseUrl, supabaseKey);

  const token = authHeader.replace("Bearer ", "");
  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
  if (authError || !user) {
    return jsonResponse({ ok: false, error: "Unauthorized." }, corsHeaders, 401);
  }

  const description = typeof body.description === "string" ? body.description.trim() : "";
  const pageUrl = typeof body.pageUrl === "string" ? body.pageUrl.trim() : "";
  const screenshotUrls: string[] = Array.isArray(body.screenshotUrls)
    ? body.screenshotUrls.filter((u): u is string => typeof u === "string")
    : [];

  if (!description || description.length < 10 || description.length > 5000) {
    return jsonResponse({ ok: false, error: "Description must be between 10 and 5000 characters." }, corsHeaders, 400);
  }
  if (screenshotUrls.length > 5) {
    return jsonResponse({ ok: false, error: "Maximum 5 screenshots allowed." }, corsHeaders, 400);
  }

  const ip = getClientIp(request);
  const now = Date.now();
  if (isRateLimited(ip, now)) {
    return jsonResponse({ ok: false, error: "Too many reports. Try again later." }, corsHeaders, 429);
  }

  // Fetch user profile to get organization_id and name
  const { data: profile } = await supabase
    .from("profiles")
    .select("organization_id, full_name")
    .eq("id", user.id)
    .maybeSingle();

  const organizationId = profile?.organization_id ?? null;

  try {
    const { error: insertError } = await supabase.from("bug_reports").insert({
      organization_id: organizationId,
      user_id: user.id,
      description,
      page_url: pageUrl || null,
      screenshot_urls: JSON.stringify(screenshotUrls),
    });

    if (insertError) {
      console.error("Failed to insert bug report:", insertError);
      return jsonResponse({ ok: false, error: "Failed to save report." }, corsHeaders, 500);
    }
  } catch (dbError) {
    console.error("DB insert error:", dbError);
    return jsonResponse({ ok: false, error: "Failed to save report." }, corsHeaders, 500);
  }

  try {
    await sendBugReportEmail({
      description,
      email: user.email ?? "unknown",
      name: profile?.full_name ?? user.email ?? "Unknown",
      pageUrl,
      screenshotCount: screenshotUrls.length,
    });
  } catch (emailError) {
    console.error("Email notification failed:", emailError);
    // Don't fail the request — the report was saved
  }

  return jsonResponse({ ok: true }, corsHeaders);
})

