      { global: { headers: { Authorization: `Bearer ${accessToken}` } } }
    );

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const body = await req.json().catch(() => null) as { targetPlan?: string; interval?: "month" | "year" } | null;
    const targetPlan = body?.targetPlan as UpgradeTargetPlan | undefined;
    const interval = body?.interval === "year" ? "year" : "month";
    if (!targetPlan || (targetPlan !== "business" && targetPlan !== "enterprise")) {
      return new Response(JSON.stringify({ error: "targetPlan must be 'business' or 'enterprise'" }), {
        status: 400,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const { data: profile, error: profileError } = await supabase
      .from("profiles")
      .select("organization_id, role")
      .eq("id", user.id)
      .single();
    if (profileError || !profile?.organization_id) {
      return new Response(JSON.stringify({ error: "No organization linked to user" }), {
        status: 400,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    if (profile.role !== "master_admin") {
      return new Response(JSON.stringify({ error: "Only master_admin can upgrade subscriptions" }), {
        status: 403,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const { data: existingSub, error: existingSubError } = await supabase
      .from("subscriptions")
      .select("stripe_subscription_id, stripe_customer_id, plan, status")
      .eq("organization_id", profile.organization_id)
      .order("updated_at", { ascending: false, nullsFirst: false })
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (existingSubError || !existingSub?.stripe_subscription_id) {
      return new Response(JSON.stringify({ error: "No active subscription found for this organization" }), {
        status: 404,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const stripeSub = await stripe.subscriptions.retrieve(existingSub.stripe_subscription_id);
    if (stripeSub.status === "canceled" || stripeSub.status === "incomplete_expired") {
      return new Response(JSON.stringify({ error: "Cannot upgrade a canceled subscription" }), {
        status: 409,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const currentPlan = normalizePlanFromStripe(stripeSub);
    const nextTier = getNextTier(currentPlan);
    if (!nextTier) {
      return new Response(JSON.stringify({ error: "Current plan is already enterprise. No further upgrades available." }), {
        status: 409,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    if (targetPlan !== nextTier) {
      return new Response(
        JSON.stringify({
          error: `Invalid upgrade path. Current plan '${currentPlan}' can only upgrade to '${nextTier}'.`,
        }),
        {
          status: 400,
          headers: { ...corsHeaders(req), "Content-Type": "application/json" },
        }
      );
    }

    const targetPriceId = interval === "year" ? ANNUAL_PRICE_IDS[targetPlan] : MONTHLY_PRICE_IDS[targetPlan];
    if (!targetPriceId) {
      return new Response(JSON.stringify({ error: `Missing Stripe price configuration for ${targetPlan} (${interval})` }), {
        status: 500,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }
    await ensureStripePriceMatchesPlan(stripe, targetPlan, targetPriceId, interval);

    const subscriptionItem = stripeSub.items.data[0];
    if (!subscriptionItem?.id) {
      throw new Error(`Stripe subscription ${stripeSub.id} has no updatable subscription item`);
    }

    const updatedSub = await stripe.subscriptions.update(stripeSub.id, {
      items: [{ id: subscriptionItem.id, price: targetPriceId }],
      proration_behavior: "create_prorations",
      metadata: {
        ...stripeSub.metadata,
        organization_id: profile.organization_id,
        supabase_user_id: user.id,
        plan: targetPlan,
      },
    });

    const updatedPlan = normalizePlanFromStripe(updatedSub);
    const orgStatus = normalizeOrgStatus(updatedSub.status);
    const stripeCustomerId =
      typeof updatedSub.customer === "string" ? updatedSub.customer : updatedSub.customer?.id ?? null;

    await upsertSubscription({
      organizationId: profile.organization_id,
      stripeCustomerId,
      stripeSubscriptionId: updatedSub.id,
      plan: updatedPlan,
      status: updatedSub.status,
      trialEnd: updatedSub.trial_end ? new Date(updatedSub.trial_end * 1000).toISOString() : null,
      periodStart: new Date(updatedSub.current_period_start * 1000).toISOString(),
      periodEnd: new Date(updatedSub.current_period_end * 1000).toISOString(),
      cancelAtPeriodEnd: updatedSub.cancel_at_period_end,
    });

    const { error: orgUpdateError } = await supabaseAdmin
      .from("organizations")
      .update({
        subscription_status: orgStatus,
        billing_owner_user_id: user.id,
        updated_at: new Date().toISOString(),
      })
      .eq("id", profile.organization_id);
    if (orgUpdateError) {
      throw new Error(`Failed to sync organization status: ${orgUpdateError.message}`);
    }

    await captureServerEvent({
      event: "plan_upgrade_started",
      distinctId: user.id,
      actorUserId: user.id,
      organizationId: profile.organization_id,
      functionName: "upgrade-subscription-plan",
      dedupeKey: `upgrade-subscription-plan:${profile.organization_id}:${updatedSub.id}:${targetPlan}`,
      properties: {
        fromPlan: currentPlan,
        toPlan: targetPlan,
      },
    });

    return new Response(
      JSON.stringify({
        success: true,
        plan: updatedPlan,
        status: updatedSub.status,
        currentPeriodEnd: new Date(updatedSub.current_period_end * 1000).toISOString(),
      }),
      {
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      }
    );
  } catch (error) {
    console.error("upgrade-subscription-plan error:", error);
    return new Response(JSON.stringify({ error: (error as Error).message }), {
      status: 500,
      headers: { ...corsHeaders(req), "Content-Type": "application/json" },
    });
  }
});

