async (req) => {
  if (req.method !== "POST") return badRequest("Method not allowed", 405);
  if (!supabaseUrl || !serviceRoleKey) return badRequest("Missing Supabase environment", 500);
  if (!smtpHost || !smtpFrom) return badRequest("Missing SMTP configuration for trial notifications", 500);

  const now = new Date();
  const summary = {
    scannedOrgs: 0,
    sentEmails: 0,
    skippedExisting: 0,
    failedEmails: 0,
    expiredOrgsMarked: 0,
  };

  const { data: trialingOrgs, error: orgError } = await supabaseAdmin
    .from("organizations")
    .select("id, name, trial_ends_at, subscription_status")
    .eq("subscription_status", "trialing")
    .not("trial_ends_at", "is", null);

  if (orgError) return badRequest(orgError.message, 500);

  for (const org of trialingOrgs ?? []) {
    summary.scannedOrgs += 1;
    const trialEndsAt = org.trial_ends_at as string;
    const daysLeft = Math.ceil((new Date(trialEndsAt).getTime() - now.getTime()) / 86_400_000);
    const kind = getNotificationKind(daysLeft);
    if (!kind) continue;

    const { data: activeSub } = await supabaseAdmin
      .from("subscriptions")
      .select("id")
      .eq("organization_id", org.id)
      .in("status", ["active", "past_due"])
      .limit(1)
      .maybeSingle();

    if (activeSub) continue;

    const { data: members, error: membersError } = await supabaseAdmin
      .rpc("get_org_user_emails", { p_org_id: org.id });

    if (membersError) {
      console.error("trial notifier: get_org_user_emails failed", org.id, membersError.message);
      continue;
    }

    for (const member of members ?? []) {
      const email = String(member.email ?? "").toLowerCase().trim();
      if (!email) continue;

      const { data: existing } = await supabaseAdmin
        .from("trial_email_notifications")
        .select("id")
        .eq("organization_id", org.id)
        .eq("email", email)
        .eq("notification_type", kind)
        .maybeSingle();

      if (existing) {
        summary.skippedExisting += 1;
        continue;
      }

      const mail = buildEmail(org.name as string, trialEndsAt, kind);
      try {
        await sendMail(email, mail.subject, mail.html);
        summary.sentEmails += 1;
        await supabaseAdmin.from("trial_email_notifications").insert({
          organization_id: org.id,
          email,
          notification_type: kind,
        });
      } catch (error) {
        summary.failedEmails += 1;
        console.error("trial notifier: email failed", org.id, email, (error as Error).message);
      }
    }

    if (kind === "expired") {
      const { error: expireError } = await supabaseAdmin
        .from("organizations")
        .update({ subscription_status: "expired", updated_at: new Date().toISOString() })
        .eq("id", org.id)
        .eq("subscription_status", "trialing");

      if (!expireError) {
        summary.expiredOrgsMarked += 1;
        await captureServerEvent({
          event: "trial_expired",
          distinctId: `org:${org.id}`,
          organizationId: org.id,
          functionName: "trial-lifecycle-notifier",
          dedupeKey: `trial-lifecycle-notifier:${org.id}:trial_expired:${new Date().toISOString().slice(0, 10)}`,
          properties: {
            previousPlan: "trial",
          },
        });
      }
    }
  }

  return new Response(JSON.stringify({ success: true, ...summary }), {
    headers: { "Content-Type": "application/json" },
  });
}

