      stripeSub = session.subscription as Stripe.Subscription;
    }

    if (!stripeSub) {
      return new Response(JSON.stringify({ error: "Checkout session does not contain a subscription" }), {
        status: 400,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const stripeCustomerId = extractStripeId(stripeSub.customer);
    const customerObject =
      typeof session.customer === "string" ? null : (session.customer as Stripe.Customer | null);
    const organizationId =
      session.metadata?.organization_id ??
      stripeSub.metadata?.organization_id ??
      customerObject?.metadata?.organization_id ??
      null;

    if (!organizationId) {
      return new Response(JSON.stringify({ error: "No organization found in checkout session metadata" }), {
        status: 400,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    if (organizationId !== profile.organization_id) {
      return new Response(JSON.stringify({ error: "Checkout session organization mismatch" }), {
        status: 403,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const { data: organization, error: orgError } = await supabaseAdmin
      .from("organizations")
      .select("billing_owner_user_id, subscription_status")
      .eq("id", organizationId)
      .single<{ billing_owner_user_id: string | null; subscription_status: OrgStatus | null }>();
    if (orgError) {
      return new Response(JSON.stringify({ error: `Unable to load organization: ${orgError.message}` }), {
        status: 400,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const canSync =
      profile.role === "master_admin" ||
      (profile.role === "read_only" && organization.billing_owner_user_id === user.id);

    if (!canSync) {
      return new Response(JSON.stringify({ error: "Only master_admin or billing owner can sync checkout sessions" }), {
        status: 403,
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      });
    }

    const plan = normalizePlanFromStripe(stripeSub);
    const orgStatus = normalizeOrgStatus(stripeSub.status);
    const billingOwnerUserId = await resolveBillingOwnerUserId(organizationId, user.id);
    const nowIso = new Date().toISOString();

    await upsertSubscription({
      organizationId,
      stripeCustomerId,
      stripeSubscriptionId: stripeSub.id,
      plan,
      status: stripeSub.status,
      trialEnd: stripeSub.trial_end ? new Date(stripeSub.trial_end * 1000).toISOString() : null,
      periodStart: new Date(stripeSub.current_period_start * 1000).toISOString(),
      periodEnd: new Date(stripeSub.current_period_end * 1000).toISOString(),
      cancelAtPeriodEnd: stripeSub.cancel_at_period_end,
    });

    const orgUpdatePayload: {
      subscription_status: OrgStatus;
      updated_at: string;
      billing_owner_user_id?: string;
    } = {
      subscription_status: orgStatus,
      updated_at: nowIso,
    };
    if (billingOwnerUserId) {
      orgUpdatePayload.billing_owner_user_id = billingOwnerUserId;
    }

    const { error: orgUpdateError } = await supabaseAdmin
      .from("organizations")
      .update(orgUpdatePayload)
      .eq("id", organizationId);
    if (orgUpdateError) {
      throw new Error(`Failed to update organization subscription status: ${orgUpdateError.message}`);
    }

    const { error: promoteError } = await supabaseAdmin
      .from("profiles")
      .update({ role: "master_admin", updated_at: nowIso })
      .eq("id", user.id)
      .eq("organization_id", organizationId);
    if (promoteError) {
      throw new Error(`Failed to promote billing user to master_admin: ${promoteError.message}`);
    }

    const checkoutAmount =
      typeof session.amount_total === "number" ? session.amount_total / 100 : PLAN_PRICES[plan];

    await captureServerEvent({
      event: "checkout_completed",
      distinctId: user.id,
      actorUserId: user.id,
      organizationId,
      functionName: "sync-checkout-session",
      dedupeKey: `checkout-completed:${sessionId}`,
      properties: {
        plan,
        billingPeriod: "monthly",
        amount: checkoutAmount,
      },
    });

    if (organization.subscription_status === "trialing" && orgStatus === "active") {
      await captureServerEvent({
        event: "trial_converted",
        distinctId: user.id,
        actorUserId: user.id,
        organizationId,
        functionName: "sync-checkout-session",
        dedupeKey: `trial-converted:${organizationId}:${sessionId}`,
        properties: {
          convertedToPlan: plan,
        },
      });
    }

    return new Response(
      JSON.stringify({
        success: true,
        organizationId,
        plan,
        status: stripeSub.status,
        orgStatus,
        stripeSubscriptionId: stripeSub.id,
      }),
      {
        headers: { ...corsHeaders(req), "Content-Type": "application/json" },
      }
    );
  } catch (error) {
    console.error("sync-checkout-session error:", error);
    return new Response(JSON.stringify({ error: (error as Error).message }), {
      status: 500,
      headers: { ...corsHeaders(req), "Content-Type": "application/json" },
    });
  }
}

