            billingPeriod: "monthly",
            amount: checkoutAmount,
            stripeEventType: event.type,
          },
        });

        break;
      }

      // ── Subscription created/updated (plan change, renewal, etc.) ─────────
      case "customer.subscription.created":
      case "customer.subscription.updated": {
        const sub = event.data.object as Stripe.Subscription;
        const syncResult = await syncFromStripeSubscription(sub, {
          billingOwnerUserIdHint: sub.metadata?.supabase_user_id ?? null,
        });

        const previousStatus =
          event.type === "customer.subscription.updated"
            ? (event.data as { previous_attributes?: { status?: string } }).previous_attributes?.status
            : undefined;
        if (previousStatus === "trialing" && sub.status === "active") {
          await captureServerEvent({
            event: "trial_converted",
            distinctId: sub.metadata?.supabase_user_id ?? `org:${syncResult.organizationId}`,
            actorUserId: sub.metadata?.supabase_user_id ?? null,
            organizationId: syncResult.organizationId,
            functionName: "stripe-webhook",
            dedupeKey: `trial-converted:${syncResult.organizationId}:${sub.id}`,
            properties: {
              convertedToPlan: syncResult.plan,
              stripeEventType: event.type,
            },
          });
        }
        break;
      }

      // ── Subscription cancelled / ended ────────────────────────────────────
      case "customer.subscription.deleted": {
        const sub = event.data.object as Stripe.Subscription;
        const stripeCustomerId = extractStripeId(sub.customer);
        const existingSub = await findSubscriptionByStripeSubId(sub.id);
        const existingByCustomerId =
          stripeCustomerId ? await findSubscriptionByStripeCustomerId(stripeCustomerId) : null;
        const organizationId =
          sub.metadata?.organization_id ??
          existingSub?.organization_id ??
          existingByCustomerId?.organization_id;

        if (!organizationId) {
          throw new Error(`No organization found for canceled stripe subscription ${sub.id}`);
        }

        const billingOwnerUserId = await resolveBillingOwnerUserId(
          organizationId,
          sub.metadata?.supabase_user_id ?? null
        );

        const { error: subscriptionError } = await supabaseAdmin
          .from("subscriptions")
          .update({
            status: "canceled",
            cancel_at_period_end: true,
            pending_downgrade_plan: null,
            pending_downgrade_effective_at: null,
            stripe_schedule_id: null,
            updated_at: new Date().toISOString(),
          })
          .eq("stripe_subscription_id", sub.id);
        if (subscriptionError) {
          throw new Error(`Failed to mark subscription canceled: ${subscriptionError.message}`);
        }

        const orgUpdatePayload: {
          subscription_status: OrgStatus;
          updated_at: string;
          billing_owner_user_id?: string;
        } = {
          subscription_status: "canceled",
          updated_at: new Date().toISOString(),
        };
        if (billingOwnerUserId) {
          orgUpdatePayload.billing_owner_user_id = billingOwnerUserId;
        }

        const { error: orgUpdateError } = await supabaseAdmin
          .from("organizations")
          .update(orgUpdatePayload)
          .eq("id", organizationId);
        if (orgUpdateError) {
          throw new Error(`Failed to update organization cancellation status: ${orgUpdateError.message}`);
        }

        // End-of-period cancellation: lock organization users to read_only.
        await demoteOrgUsersToReadOnly(organizationId);

        await captureServerEvent({
          event: "subscription_canceled",
          distinctId: billingOwnerUserId ?? `org:${organizationId}`,
          actorUserId: billingOwnerUserId ?? null,
          organizationId,
          functionName: "stripe-webhook",
          dedupeKey: `subscription-canceled:${sub.id}`,
          properties: {
            plan: normalizePlanFromStripe(sub),
            stripeEventType: event.type,
          },
        });
        break;
      }

      // ── Payment failed ────────────────────────────────────────────────────
      case "invoice.payment_failed": {
        const invoice = event.data.object as Stripe.Invoice;
        const stripeSubId = invoice.subscription as string;
        if (stripeSubId) {
          const existingSub = await findSubscriptionByStripeSubId(stripeSubId);
          const { error: subscriptionError } = await supabaseAdmin
            .from("subscriptions")
            .update({ status: "past_due", updated_at: new Date().toISOString() })
            .eq("stripe_subscription_id", stripeSubId);
          if (subscriptionError) {
            throw new Error(`Failed to mark subscription past_due: ${subscriptionError.message}`);
          }
          if (existingSub?.organization_id) {
            const { error: orgUpdateError } = await supabaseAdmin
              .from("organizations")
              .update({ subscription_status: "past_due", updated_at: new Date().toISOString() })
              .eq("id", existingSub.organization_id);
            if (orgUpdateError) {
              throw new Error(`Failed to mark organization past_due: ${orgUpdateError.message}`);
            }
          }
        }
        break;
      }

      default:
        console.log(`Unhandled event type: ${event.type}`);
    }

    return new Response(JSON.stringify({ received: true }), {
      headers: { "Content-Type": "application/json" },
    });

  } catch (error) {
    console.error("Error processing webhook:", error);
    return new Response(JSON.stringify({ error: (error as Error).message }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }
}

