Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders(req) });
  }

  if (req.method !== "POST") {
    return json(req, 405, { error: "Method not allowed" });
  }

  try {
    if (!stripe) {
      return json(req, 500, { error: "Missing STRIPE_SECRET_KEY in function secrets" });
    }

    const rawAuthHeader = req.headers.get("Authorization") ?? req.headers.get("authorization");
    const accessToken = extractBearerToken(rawAuthHeader);
    if (!accessToken) {
      return json(req, 401, { error: "Missing authorization header" });
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: `Bearer ${accessToken}` } } }
    );

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return json(req, 401, { error: "Unauthorized" });
    }

    const body = await req.json().catch(() => null) as { targetPlan?: string; interval?: "month" | "year" } | null;
    const targetPlan = body?.targetPlan as DowngradeTargetPlan | undefined;
    const interval = body?.interval === "year" ? "year" : "month";
    if (!targetPlan || (targetPlan !== "starter" && targetPlan !== "business")) {
      return json(req, 400, { error: "targetPlan must be 'starter' or 'business'" });
    }

    const { data: profile, error: profileError } = await supabase
      .from("profiles")
      .select("organization_id, role")
      .eq("id", user.id)
      .single();
    if (profileError || !profile?.organization_id) {
      return json(req, 400, { error: "No organization linked to user" });
    }
    if (profile.role !== "master_admin") {
      return json(req, 403, { error: "Only master_admin can schedule downgrades" });
    }

    const { data: existingSub, error: existingSubError } = await supabase
      .from("subscriptions")
      .select("stripe_subscription_id, stripe_schedule_id")
      .eq("organization_id", profile.organization_id)
      .order("updated_at", { ascending: false, nullsFirst: false })
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (existingSubError) throw existingSubError;
    if (!existingSub?.stripe_subscription_id) {
      return json(req, 404, { error: "No active subscription found for this organization" });
    }

    const stripeSub = await stripe.subscriptions.retrieve(existingSub.stripe_subscription_id);
    if (stripeSub.status === "canceled" || stripeSub.status === "incomplete_expired") {
      return json(req, 404, { error: "No active paid subscription found for this organization" });
    }
    if (stripeSub.cancel_at_period_end) {
      return json(req, 409, {
        error: "Cancellation is already scheduled. Resume subscription before scheduling a downgrade.",
      });
    }

    const currentPlan = normalizePlanFromStripe(stripeSub);
    if (PLAN_RANK[targetPlan] >= PLAN_RANK[currentPlan]) {
      return json(req, 400, {
        error: `Invalid downgrade path. Current plan '${currentPlan}' must downgrade to a lower tier.`,
      });
    }

    const targetPriceId = interval === "year" ? ANNUAL_PRICE_IDS[targetPlan] : MONTHLY_PRICE_IDS[targetPlan];
    if (!targetPriceId) {
      return json(req, 500, { error: `Missing Stripe price configuration for ${targetPlan} (${interval})` });
    }
    await ensureStripePriceMatchesPlan(stripe, targetPlan, targetPriceId, interval);

    const usage = await getUsageSnapshot(supabase, profile.organization_id);
    const limits = PLAN_LIMITS[targetPlan];
    if (limits.maxUsers !== null && usage.seatsUsed > limits.maxUsers) {
      return json(req, 409, {
        error: `Usage exceeds ${targetPlan} user limit (${usage.seatsUsed}/${limits.maxUsers}). Reduce users/invites before downgrading.`,
        code: "DOWNGRADE_LIMIT_USERS",
      });
    }
    if (limits.maxItems !== null && usage.itemsCount > limits.maxItems) {
      return json(req, 409, {
        error: `Usage exceeds ${targetPlan} item limit (${usage.itemsCount}/${limits.maxItems}). Reduce items before downgrading.`,
        code: "DOWNGRADE_LIMIT_ITEMS",
      });
    }

    const currentItem = stripeSub.items.data[0];
    const currentPriceId = currentItem?.price?.id ?? "";
    const currentQuantity = currentItem?.quantity ?? 1;
    if (!currentPriceId) {
      throw new Error(`Stripe subscription ${stripeSub.id} has no active subscription item price`);
    }

    const currentPeriodStart = stripeSub.current_period_start;
    const currentPeriodEnd = stripeSub.current_period_end;
    const effectiveAtIso = new Date(currentPeriodEnd * 1000).toISOString();

    let scheduleId = extractStripeId(stripeSub.schedule) ?? existingSub.stripe_schedule_id ?? null;
    if (!scheduleId) {
      const createdSchedule = await stripe.subscriptionSchedules.create({
        from_subscription: stripeSub.id,
      });
      scheduleId = createdSchedule.id;
    }

    const schedule = await stripe.subscriptionSchedules.update(scheduleId, {
      end_behavior: "release",
      metadata: {
        ...stripeSub.metadata,
        organization_id: profile.organization_id,
        supabase_user_id: user.id,
        pending_downgrade_plan: targetPlan,
      },
      phases: [
        {
          start_date: currentPeriodStart,
          end_date: currentPeriodEnd,
          items: [{ price: currentPriceId, quantity: currentQuantity }],
          proration_behavior: "none",
          metadata: {
            ...stripeSub.metadata,
            organization_id: profile.organization_id,
            supabase_user_id: user.id,
            plan: currentPlan,
          },
        },
        {
          start_date: currentPeriodEnd,
          items: [{ price: targetPriceId, quantity: currentQuantity }],
          proration_behavior: "none",
          metadata: {
            ...stripeSub.metadata,
            organization_id: profile.organization_id,
            supabase_user_id: user.id,
            plan: targetPlan,
            scheduled_downgrade_from: currentPlan,
          },
        },
      ],
    });

    const { error: subUpdateError } = await supabaseAdmin
      .from("subscriptions")
      .update({
        stripe_subscription_id: stripeSub.id,
        stripe_customer_id: extractStripeId(stripeSub.customer),
        plan: currentPlan,
        status: stripeSub.status,
        trial_ends_at: stripeSub.trial_end ? new Date(stripeSub.trial_end * 1000).toISOString() : null,
        current_period_start: new Date(currentPeriodStart * 1000).toISOString(),
        current_period_end: effectiveAtIso,
        cancel_at_period_end: stripeSub.cancel_at_period_end,
        pending_downgrade_plan: targetPlan,
        pending_downgrade_effective_at: effectiveAtIso,
        stripe_schedule_id: schedule.id,
        updated_at: new Date().toISOString(),
      })
      .eq("organization_id", profile.organization_id);
    if (subUpdateError) {
      throw new Error(`Failed to persist pending downgrade metadata: ${subUpdateError.message}`);
    }

    const { error: orgUpdateError } = await supabaseAdmin
      .from("organizations")
      .update({
        subscription_status: normalizeOrgStatus(stripeSub.status),
        billing_owner_user_id: user.id,
        updated_at: new Date().toISOString(),
      })
      .eq("id", profile.organization_id);
    if (orgUpdateError) {
      throw new Error(`Failed to sync organization billing owner: ${orgUpdateError.message}`);
    }

    await captureServerEvent({
      event: "plan_downgrade_scheduled",
      distinctId: user.id,
      actorUserId: user.id,
      organizationId: profile.organization_id,
      functionName: "schedule-subscription-downgrade",
      dedupeKey: `schedule-subscription-downgrade:${profile.organization_id}:${schedule.id}`,
      properties: {
        fromPlan: currentPlan,
        toPlan: targetPlan,
      },
    });

    return json(req, 200, {
      success: true,
      currentPlan,
      targetPlan,
      effectiveAt: effectiveAtIso,
      status: stripeSub.status,
      stripeScheduleId: schedule.id,
    });
  } catch (error) {
    console.error("schedule-subscription-downgrade error:", error);
    return json(req, 500, { error: (error as Error).message });
  }
})

